rows = [
[7], [], [3,7,9], [], [1,2], [7], [5], [5], [], [], [], [8], [], [0,8], [4], [1,4,10], [], [0], [], [], [3,4,9], [5,7], [1], [3,7], [], [], [], [5,9]
]
# rows positions 0-based; construct input and fill aligned gaps
R,C=28,11
grid=[[1]*C for _ in range(R)]
for r,cs in enumerate(rows):
    for c in cs: grid[r][c]=7
out=[row[:] for row in grid]
for r in range(R):
    cs=[c for c,v in enumerate(grid[r]) if v==7]
    if len(cs)>1:
        for c in range(min(cs)+1,max(cs)): out[r][c]=3
for c in range(C):
    rs=[r for r in range(R) if grid[r][c]==7]
    if len(rs)>1:
        for r in range(min(rs)+1,max(rs)): out[r][c]=3
print('\n'.join(' '.join(map(str,row)) for row in out))

